fn heading_cost(dist: f64, speed: f64) -> f64 {
  let t: f64 = dist / speed;
  if t > 10.0 {
    return 10.0;
  }
  return t;
}

fn clamp(x: f64, lo: f64, hi: f64) -> f64 {
  if x < lo {
    return lo;
  }
  if x > hi {
    return hi;
  }
  return x;
}

fn slalom_katamaran(wind: f64, gust: f64) -> i32 {
  let i: i32 = 0;
  let steps: i32 = 0;
  while i < 8 {
    if wind + gust > 12.0 {
      steps = steps + 1;
    }
    i = i + 1;
  }
  return steps;
}

fn dot_product(a: [f64; 4], b: [f64; 4]) -> f64 {
  let i: i32 = 0;
  let s: f64 = 0.0;
  while i < 4 {
    s = s + a[i] * b[i];
    i = i + 1;
  }
  return s;
}

fn max_in_array(a: [f64; 4]) -> f64 {
  let m: f64 = a[0];
  let i: i32 = 1;
  while i < 4 {
    if a[i] > m {
      m = a[i];
    }
    i = i + 1;
  }
  return m;
}

fn battery_used(amps: i32, seconds: i32) -> i32 {
  return amps * seconds / 3600;
}

fn nested_sweep() -> f64 {
  let i: i32 = 0;
  let acc: f64 = 0.0;
  while i < 6 {
    let j: i32 = 0;
    while j < 6 {
      acc = acc + 0.5;
      j = j + 1;
    }
    i = i + 1;
  }
  return acc;
}

fn cast_degrees(deg: i64) -> f64 {
  let d: f64 = deg as f64;
  return d * 3.141592653589793 / 180.0;
}

fn sqrt_margin(margin: f64) -> f64 {
  if margin < 0.0 {
    return 0.0;
  }
  return sqrt(margin);
}

fn catamaran_plan(wind: f64) -> f64 {
  let gains: [f64; 3] = [1.0, 1.5, 2.0];
  let i: i32 = 0;
  let best: f64 = 0.0;
  while i < 3 {
    let v: f64 = gains[i] * wind;
    best = max(best, v);
    i = i + 1;
  }
  return best;
}

fn spin(x: i32) -> i32 {
  while x > 0 {
    x = x;
  }
  return x;
}

fn fact(n: i32) -> i32 {
  if n < 2 {
    return 1;
  }
  return n * fact(n - 1);
}

